//! HTTP／N-API 共用原共享 BPP 普通及 Benders application，不绕过其预算和完整注册复验。
//! Original shared BPP ordinary and Benders applications for HTTP/N-API, retaining budgets and full-registration validation.

use std::time::{Duration, Instant};
use ospf_rust_core::solver::SolveOptions;
use ospf_rust_framework::solver::FixedRecourseConfig;
use ospf_rust_framework_bpp::application::{DiscreteLoadingApplicationService, DiscreteLoadingBendersApplicationService, DiscreteLoadingBendersOptions,
    DiscreteLoadingCertificationResult, DiscreteLoadingCertificationService, DiscreteLoadingSolveOptions};
use ospf_rust_bridge::{BppLoadingContext, BridgeError, JobView, Result, SolveRequest, encode_bpp_loading_application, encode_bpp_loading_benders, encode_bpp_loading_certification};
use crate::{NativeEngine, create_solver};
use crate::linear_identity::bind_cancelled_identity;

impl NativeEngine {
    pub(crate) fn start_bpp_loading(&self, request: SolveRequest) -> Result<JobView> {
        let configuration = request.bpp_loading_options.as_ref().ok_or_else(|| BridgeError::new("InvalidInput", "missing BPP loading configuration"))?;
        if configuration.benders.is_some() && configuration.partition.is_some() { return Err(BridgeError::new("InvalidInput", "BPP Benders and partition CG are exclusive")); }
        if configuration.partition.is_some() { return self.start_bpp_partition(request); }
        let solver = create_solver(configuration.backend.id(), None)?;
        let context = BppLoadingContext::from_artifact(&request.model)?; context.application_model()?;
        if let Some(benders) = &configuration.benders {
            benders.validate(&context)?;
            if let Some(finishing) = &benders.source_milp_finishing {
                finishing.accelerator_budget(Duration::from_millis(u64::from(request.time_limit_ms.unwrap_or(60_000))))?;
            }
        }
        if configuration.benders.is_some() { return self.start_bpp_loading_benders(request, solver); }
        let source = request.model.clone();
        self.start_encoded(request, move |options| {
            let handle = options.cancellation_handle.ok_or_else(|| BridgeError::new("ExecutionFailure", "missing BPP loading cancellation handle"))?;
            let result = DiscreteLoadingApplicationService::solve(|| {
                let context = BppLoadingContext::from_artifact(&source)
                    .map_err(|error| ospf_rust_core::SolverError::ContractViolation(error.to_string()))?;
                context.into_registration()
            }, DiscreteLoadingSolveOptions { time_limit: options.time_limit.unwrap_or(Duration::from_secs(60)), ..Default::default() }, handle,
            |model, remaining, handle| {
                let mut report = solver.solve_linear_report_with_options(model, &SolveOptions {
                    time_limit: Some(remaining), cancellation_handle: Some(handle), progress_reporter: options.progress_reporter, ..Default::default()
                })?;
                bind_cancelled_identity(&mut report, model)?;
                Ok(report)
            }).map_err(|error| BridgeError::new(error.solver_error_class().code(), error))?;
            encode_bpp_loading_application(&result, &source)
        })
    }

    fn start_bpp_loading_benders(&self, request: SolveRequest, solver: std::sync::Arc<dyn ospf_rust_core::solver::Solver>) -> Result<JobView> {
        let configuration = request.bpp_loading_options.clone().ok_or_else(|| BridgeError::new("InvalidInput", "missing BPP loading configuration"))?;
        let benders = configuration.benders.ok_or_else(|| BridgeError::new("InvalidInput", "missing BPP Benders configuration"))?;
        #[cfg(feature = "scip")]
        let solver: std::sync::Arc<dyn ospf_rust_core::solver::Solver> = if configuration.backend == ospf_rust_bridge::NativeBackend::Scip {
            use ospf_rust_core::solver::solvers::scip::{SCIPConfig, SCIPSolver};
            std::sync::Arc::new(SCIPSolver::with_config(SCIPConfig::default().with_output(false).with_lp_subproblem_defaults()))
        } else { solver };
        let source = request.model.clone();
        self.start_encoded(request, move |options| {
            let started = Instant::now();
            let handle = options.cancellation_handle.ok_or_else(|| BridgeError::new("ExecutionFailure", "missing BPP Benders cancellation handle"))?;
            let budget = options.time_limit.unwrap_or(Duration::from_secs(60));
            let accelerator_budget = benders.source_milp_finishing.as_ref().map(|finishing| finishing.accelerator_budget(budget)).transpose()?.unwrap_or(budget);
            let mut first = None; let mut initial = None; let mut partition = Default::default();
            if !handle.is_cancelled() && !budget.is_zero() {
                let context = BppLoadingContext::from_artifact(&source)?;
                partition = context.benders_partition_options(&benders.recourse_resources)?;
                initial = Some(context.application_snapshot()?); first = Some(context);
            }
            // 初始模型必须在线程内创建；其构造时间计入同一总预算，回退始终创建全新会话。
            // Build the initial model inside the worker and charge the same total budget; fallback always creates a fresh session.
            let result = DiscreteLoadingBendersApplicationService::solve(|| {
                let context = match first.take() {
                    Some(context) => context,
                    None => BppLoadingContext::from_artifact(&source).map_err(|error| ospf_rust_core::SolverError::ContractViolation(error.to_string()))?,
                };
                context.into_registration()
            }, DiscreteLoadingBendersOptions { partition, config: FixedRecourseConfig {
                iteration_limit: benders.iteration_limit.map_or(128, |value| value as usize), time_limit: accelerator_budget.saturating_sub(started.elapsed()),
                tolerance: 1e-7, recover_missing_certificates: benders.recover_missing_certificates.unwrap_or(true),
            }, fallback_to_milp: benders.fallback_to_milp.unwrap_or(false) }, handle, |model, remaining, handle| {
                let mut report = solver.solve_linear_report_with_options(model, &SolveOptions { time_limit: Some(remaining),
                    cancellation_handle: Some(handle), progress_reporter: options.progress_reporter, ..Default::default() })?;
                bind_cancelled_identity(&mut report, model)?; Ok(report)
            }).map_err(|error| BridgeError::new(error.solver_error_class().code(), error))?;
            let acceleration = encode_bpp_loading_benders(&result, &source, initial.as_ref(), &benders)?;
            if benders.source_milp_finishing.is_none() { return Ok(acceleration); }
            let remaining = budget.saturating_sub(started.elapsed());
            let factory = || BppLoadingContext::from_artifact(&source)
                .map_err(|error| ospf_rust_core::SolverError::ContractViolation(error.to_string()))?.into_registration();
            let solve = |model: &ospf_rust_core::model::intermediate::LinearTriadModel, remaining, handle: &ospf_rust_core::solver::SolveHandle| {
                let mut report = solver.solve_linear_report_with_options(model, &SolveOptions { time_limit: Some(remaining),
                    cancellation_handle: Some(handle), progress_reporter: options.progress_reporter, ..Default::default() })?;
                bind_cancelled_identity(&mut report, model)?; Ok(report)
            };
            // 加速阶段可能未注册即耗尽自己的预算；仍可使用预留量创建真实完整源，不伪造旧注册。
            // The accelerator may exhaust its own budget before registration; use reserved time for a real full source without fabricating old registration.
            let finished = if result.result.registration.is_some() {
                DiscreteLoadingCertificationService::solve(result.result, factory, DiscreteLoadingSolveOptions { time_limit: remaining, ..Default::default() }, handle, solve)
            } else if !handle.is_cancelled() && !remaining.is_zero() {
                DiscreteLoadingApplicationService::solve(factory, DiscreteLoadingSolveOptions { time_limit: remaining, ..Default::default() }, handle, solve)
                    .map(|result| DiscreteLoadingCertificationResult { certification_report: result.registration.as_ref().map(|_| result.report.clone()), result, certification_error: None })
            } else { Ok(DiscreteLoadingCertificationResult { result: result.result, certification_report: None, certification_error: None }) }
                .map_err(|error| BridgeError::new(error.solver_error_class().code(), error))?;
            encode_bpp_loading_certification(&acceleration, &finished, &source)
        })
    }
}

